(()=>{'use strict';
const $=id=>document.getElementById(id),keyM='p727_missions_v1',keyD='p727_diaries_v1';
const defaults=[{id:'m1',name:'Phác hình cơ bản',code:'ART-L1-001',path:'Art',level:1,pre:'',active:true},{id:'m2',name:'Khối và ánh sáng',code:'ART-L1-002',path:'Art',level:1,pre:'m1',active:true},{id:'m3',name:'Màu sắc cảm xúc',code:'ART-L2-003',path:'Art',level:2,pre:'m2',active:true},{id:'m4',name:'Nhịp điệu cơ bản',code:'PIA-L1-001',path:'Piano',level:1,pre:'',active:true}];
const students=[{id:'s1',name:'Nguyễn An Nhiên',birth:'2019-04-08',gender:'female',classes:['Art A']},{id:'s2',name:'Trần Minh Khang',birth:'2018-06-15',gender:'male',classes:['Art A','Art B']},{id:'s3',name:'Lê Gia Hân',birth:'2020-02-03',gender:'female',classes:['Art A','Piano A']},{id:'s4',name:'Phạm Quốc Bảo',birth:'2017-09-21',gender:'male',classes:['Piano A']}];
const schedule={'Art A':'2026-10-17 · 16:00','Art B':'2026-10-17 · 18:00','Piano A':'2026-10-17 · 17:00'};
const read=(key,fallback)=>{try{let v=JSON.parse(localStorage.getItem(key));return Array.isArray(v)?v:fallback}catch{return fallback}},save=(key,data)=>localStorage.setItem(key,JSON.stringify(data));
let missions=read(keyM,defaults),diaries=read(keyD,[]),mode=null,editing=null,dirty=false,focusBefore=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),age=b=>{let d=new Date(b+'T00:00:00'),n=new Date('2026-10-17T12:00:00');return n.getFullYear()-d.getFullYear()-(n.getMonth()<d.getMonth()||(n.getMonth()===d.getMonth()&&n.getDate()<d.getDate())?1:0)},personLabel=p=>(p.gender==='male'?'♂ ':'♀ ')+p.name+' - '+age(p.birth)+' tuổi',gender=p=>'<span class="sex '+p.gender+'">'+(p.gender==='male'?'♂':'♀')+'</span>';
function showPage(){const page=location.hash==='#diaries'?'diaries':'missions';document.querySelectorAll('.page').forEach(e=>e.classList.toggle('active',e.id===page));document.querySelectorAll('[data-page]').forEach(e=>e.classList.toggle('active',e.dataset.page===page));}
window.addEventListener('hashchange',showPage);showPage();
function renderM(){let q=$('mq').value.toLowerCase(),p=$('mpath').value,l=$('mlevel').value;let items=missions.filter(x=>(x.name+' '+x.code).toLowerCase().includes(q)&&(!p||x.path===p)&&(!l||String(x.level)===l));$('missionRows').innerHTML=items.map(x=>'<tr><td><strong>'+esc(x.name)+'</strong></td><td><code>'+esc(x.code)+'</code></td><td>'+esc(x.path)+'</td><td>'+x.level+'</td><td>'+esc(missions.find(y=>y.id===x.pre)?.code||'—')+'</td><td><span class="pillish">'+(x.active?'Active':'Inactive')+'</span></td><td><button class="btn" data-edit-m="'+esc(x.id)+'">Edit</button></td></tr>').join('')||'<tr><td colspan="7" class="empty">Không có Mission phù hợp</td></tr>';}
function renderD(){let q=$('dq').value.toLowerCase(),c=$('dclass').value;let items=diaries.filter(x=>{let s=students.find(y=>y.id===x.studentId),m=missions.find(y=>y.id===x.missionId);return(!c||x.cls===c)&&((s?.name||'')+' '+(m?.name||'')+' '+x.cls).toLowerCase().includes(q)});$('diaryRows').innerHTML=items.map(x=>{let s=students.find(y=>y.id===x.studentId),m=missions.find(y=>y.id===x.missionId);return '<tr><td>'+(s?gender(s)+' '+esc(s.name)+' - '+age(s.birth)+' tuổi':'Unknown')+'</td><td>'+esc(x.cls)+'</td><td>'+esc(x.session)+'</td><td><strong>'+esc(m?.name||'Unknown')+'</strong><div class="mini">'+esc(m?.code||'')+'</div></td><td>'+x.interest+' / 5</td><td>'+(x.completed?'✓ Hoàn thành':'Chưa hoàn thành')+'</td><td><button class="btn" data-edit-d="'+esc(x.id)+'">Edit</button></td></tr>'}).join('')||'<tr><td colspan="7" class="empty">Chưa có nhật ký. Chọn “Ghi nhật ký” để tạo bản demo.</td></tr>';}
['mq','mpath','mlevel'].forEach(x=>$(x).addEventListener('input',renderM));['dq','dclass'].forEach(x=>$(x).addEventListener('input',renderD));renderM();renderD();
function drawer(title,body,footer){focusBefore=document.activeElement;$('drawerHost').innerHTML='<button class="peekBackdrop" aria-label="Đóng drawer"></button><aside class="peek" role="dialog" aria-modal="true" aria-label="'+esc(title)+'" tabindex="-1"><header class="peekHeader"><div><div class="mini">PINO LEARNING · '+(mode==='mission'?'PAP-723':'PAP-724')+'</div><h2>'+esc(title)+'</h2></div><button class="btn" id="xClose" type="button">×</button></header><div class="peekBody">'+body+'<div id="err" class="error" hidden></div></div><footer class="peekFooter">'+footer+'</footer></aside>';$('xClose').onclick=close;$('drawerHost').querySelector('.peekBackdrop').onclick=close;const pane=$('drawerHost').querySelector('.peek');pane.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();close()}if(e.key==='Tab'){let f=[...pane.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled)')].filter(x=>x.offsetParent!==null);if(!f.length)return;let a=f[0],b=f[f.length-1];if(e.shiftKey&&document.activeElement===a){e.preventDefault();b.focus()}else if(!e.shiftKey&&document.activeElement===b){e.preventDefault();a.focus()}}});pane.querySelector('.peekBody').addEventListener('input',()=>dirty=true);pane.querySelector('.peekBody').addEventListener('change',()=>dirty=true);pane.focus();}
function close(){if(dirty&&!confirm('Có thay đổi chưa lưu. Bạn muốn đóng drawer?'))return;mode=null;editing=null;dirty=false;$('drawerHost').innerHTML='';if(focusBefore?.isConnected)focusBefore.focus();}
function error(s){$('err').textContent=s;$('err').hidden=false;}
function openMission(id){mode='mission';editing=id||null;dirty=false;const x=missions.find(v=>v.id===id)||{name:'',code:'',path:'Art',level:1,pre:'',active:true};drawer(id?'Chỉnh sửa Mission':'Tạo Mission',`<form id="missionForm"><div class="field"><label>Name</label><input id="mn" required value="${esc(x.name)}" placeholder="Ví dụ: Phác hình cơ bản"></div><div class="field"><label>Code · duy nhất</label><input id="mc" required value="${esc(x.code)}" placeholder="ART-L1-001"></div><div class="field"><label>Path</label><select id="mp"><option ${x.path==='Art'?'selected':''}>Art</option><option ${x.path==='Piano'?'selected':''}>Piano</option></select></div><div class="field"><label>Level</label><select id="ml">${[1,2,3,4,5].map(n=>'<option '+(x.level===n?'selected':'')+'>'+n+'</option>').join('')}</select></div><div class="field"><label>Prerequisite · optional</label><select id="mpr"><option value="">Không có</option>${missions.filter(y=>y.id!==id).map(y=>'<option value="'+esc(y.id)+'" '+(x.pre===y.id?'selected':'')+'>'+esc(y.name)+' — '+esc(y.code)+'</option>').join('')}</select><small class="hint">Không tự tham chiếu hoặc tạo dependency cycle.</small></div><div class="field"><label><input type="checkbox" id="ma" ${x.active?'checked':''} style="width:auto"> Active</label></div></form>`,'<button class="btn" id="cancel">Hủy</button><button class="btn primary" id="saveM">Lưu Mission</button>');$('cancel').onclick=close;$('saveM').onclick=()=>{if(!$('missionForm').reportValidity())return;let name=$('mn').value.trim(),code=$('mc').value.trim().toUpperCase(),pre=$('mpr').value;if(missions.some(y=>y.code.toLowerCase()===code.toLowerCase()&&y.id!==id))return error('Code đã tồn tại. Hãy chọn Code khác.');let cur=pre;const seen=new Set([id]);while(cur){if(seen.has(cur))return error('Prerequisite tạo vòng lặp.');seen.add(cur);cur=missions.find(y=>y.id===cur)?.pre||'';}const v={id:id||'m'+Date.now(),name,code,path:$('mp').value,level:Number($('ml').value),pre,active:$('ma').checked};missions=id?missions.map(y=>y.id===id?v:y):[...missions,v];save(keyM,missions);dirty=false;close();renderM();renderD();};}
function openDiary(id){mode='diary';editing=id||null;dirty=false;let x=diaries.find(v=>v.id===id)||{studentId:'',cls:'',missionId:'',interest:3,completed:false,notes:''};let student=students.find(s=>s.id===x.studentId)||null,mission=missions.find(m=>m.id===x.missionId)||null;
drawer(id?'Chỉnh sửa Classroom Diary':'Ghi nhật ký lớp học',`<form id="diaryForm"><div class="field"><label>Student ⓘ</label><input id="studentSearch" autocomplete="off" placeholder="Nhập ít nhất 3 ký tự..." value="${student?esc(personLabel(student)):''}"><small class="hint">Tìm theo tên · ♂ xanh, ♀ hồng · tuổi từ ngày sinh</small><div id="studentOptions" class="suggest" hidden></div></div><div class="field"><label>Running Class</label><select id="cls" required><option value="">Chọn lớp</option></select></div><div class="field"><label>Session</label><div class="pillish" id="sessionLabel">Tự xác định từ Running Class</div><div class="hint">Không chọn Session thủ công.</div></div><div class="field"><label>Mission · Name — Code</label><input id="missionSearch" autocomplete="off" placeholder="Tìm Name hoặc Code..." value="${mission?esc(mission.name+' — '+mission.code):''}"><div id="missionOptions" class="suggest" hidden></div><small class="hint">Mỗi lần lưu đúng một Mission.</small></div><div class="field"><label>Độ hứng thú</label><div class="rating">${[1,2,3,4,5].map(n=>'<label><input type="radio" name="interest" value="'+n+'" '+(Number(x.interest)===n?'checked':'')+'> '+n+'</label>').join('')}</div></div><div class="field"><label><input id="completed" type="checkbox" style="width:auto" ${x.completed?'checked':''}> Xác nhận hoàn thành nhiệm vụ</label></div><div class="field"><label>Lưu ý</label><textarea id="notes" placeholder="Nhận xét về quá trình học...">${esc(x.notes)}</textarea></div></form>`,id?'<button class="btn" id="cancel">Hủy</button><button class="btn primary" id="saveClose">Lưu thay đổi</button>':'<button class="btn" id="cancel">Hủy</button><button class="btn soft" id="saveAgain">Lưu & thêm Mission</button><button class="btn primary" id="saveClose">Lưu & đóng</button>');
let selectedStudent=student,selectedMission=mission;const fillClasses=()=>{$('cls').innerHTML='<option value="">Chọn lớp</option>'+(selectedStudent?.classes||[]).map(c=>'<option '+(c===x.cls?'selected':'')+'>'+esc(c)+'</option>').join('');updateSession()},updateSession=()=>{$('sessionLabel').textContent=schedule[$('cls').value]||'Chưa xác định buổi học'};fillClasses();$('cls').onchange=updateSession;
$('studentSearch').oninput=()=>{selectedStudent=null;selectedMission=selectedMission;fillClasses();let q=$('studentSearch').value.trim().toLowerCase();$('studentOptions').hidden=q.length<3;$('studentOptions').innerHTML=students.filter(s=>s.name.toLowerCase().includes(q)).map(s=>'<button type="button" data-student="'+esc(s.id)+'">'+gender(s)+' '+esc(s.name)+' - '+age(s.birth)+' tuổi</button>').join('')||'<div class="hint" style="padding:12px">Không tìm thấy học viên</div>';$('studentOptions').querySelectorAll('button').forEach(b=>b.onclick=()=>{selectedStudent=students.find(s=>s.id===b.dataset.student);$('studentSearch').value=personLabel(selectedStudent);$('studentOptions').hidden=true;x.cls='';fillClasses();dirty=true;});};
$('missionSearch').oninput=()=>{selectedMission=null;let q=$('missionSearch').value.toLowerCase();$('missionOptions').hidden=!q;$('missionOptions').innerHTML=missions.filter(m=>m.active&&(m.name+' '+m.code).toLowerCase().includes(q)).map(m=>'<button type="button" data-mission="'+esc(m.id)+'">'+esc(m.name)+' — '+esc(m.code)+'</button>').join('')||'<div class="hint" style="padding:12px">Không tìm thấy Mission</div>';$('missionOptions').querySelectorAll('button').forEach(b=>b.onclick=()=>{selectedMission=missions.find(m=>m.id===b.dataset.mission);$('missionSearch').value=selectedMission.name+' — '+selectedMission.code;$('missionOptions').hidden=true;dirty=true;});};
function submit(again){if(!selectedStudent||!selectedMission||!$('cls').value)return error('Chọn Student, Running Class và một Mission từ kết quả tìm kiếm.');let cls=$('cls').value,session=schedule[cls];if(!session)return error('Không xác định được Session từ Running Class.');if(diaries.some(y=>y.id!==id&&y.studentId===selectedStudent.id&&y.cls===cls&&y.session===session&&y.missionId===selectedMission.id))return error('Diary này đã tồn tại. Hãy dùng Edit bản ghi cũ.');let now=new Date().toISOString(),row={id:id||'d'+Date.now(),studentId:selectedStudent.id,cls,session,missionId:selectedMission.id,interest:Number(document.querySelector('input[name="interest"]:checked').value),completed:$('completed').checked,notes:$('notes').value,createdAt:x.createdAt||now,updatedAt:now};diaries=id?diaries.map(y=>y.id===id?row:y):[...diaries,row];save(keyD,diaries);renderD();dirty=false;if(!again){close();return}x=row;editing=null;$('missionSearch').value='';selectedMission=null;$('completed').checked=false;$('notes').value='';document.querySelector('input[name="interest"][value="3"]').checked=true;$('err').hidden=true;dirty=false;}
$('cancel').onclick=close;$('saveClose').onclick=()=>submit(false);if($('saveAgain'))$('saveAgain').onclick=()=>submit(true);}
$('newMission').onclick=()=>openMission();$('newDiary').onclick=()=>openDiary();document.addEventListener('click',e=>{const m=e.target.closest('[data-edit-m]'),d=e.target.closest('[data-edit-d]');if(m)openMission(m.dataset.editM);if(d)openDiary(d.dataset.editD);});
})();